import static java.nio.charset.StandardCharsets.UTF_8;
import org.springframework.http.*;
import org.springframework.http.converter.*;
import org.springframework.http.converter.json.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.*;
import static org.springframework.test.web.servlet
        .request.MockMvcRequestBuilders.*;

class BusinessRuleException extends RuntimeException {
    BusinessRuleException(String m) { super(m); }
}
class RequestNotFoundException extends RuntimeException {
    RequestNotFoundException(long id) {
        super("申請(ID=" + id + ")が見つかりません");
    }
}
record RequestDetail(long id, String status) {}

@RestController
@RequestMapping("/api/requests")
class RequestApiController {
    // id → 状態(本物は Service と DB。ここでは Map で代用)
    Map<Long, String> status = new HashMap<>(
            Map.of(1L, "SUBMITTED", 2L, "APPROVED"));

    @PostMapping("/{id}/approve")
    RequestDetail approve(@PathVariable("id") long id) {
        String s = status.get(id);
        if (s == null) {
            throw new RequestNotFoundException(id);
        }
        if (!s.equals("SUBMITTED")) {
            throw new BusinessRuleException(
                    "承認済の申請は変更できません");
        }
        status.put(id, "APPROVED");
        return new RequestDetail(id, "APPROVED");
    }

    @ExceptionHandler(BusinessRuleException.class)
    ProblemDetail onRule(BusinessRuleException e) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(
                HttpStatus.CONFLICT, e.getMessage());
        pd.setTitle("業務ルール違反");
        return pd;
    }

    @ExceptionHandler(RequestNotFoundException.class)
    ProblemDetail onNotFound(RequestNotFoundException e) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(
                HttpStatus.NOT_FOUND, e.getMessage());
        pd.setTitle("申請が見つかりません");
        return pd;
    }
}

MockMvc mvc = MockMvcBuilders
    .standaloneSetup(new RequestApiController())
    .setMessageConverters(
        new StringHttpMessageConverter(UTF_8),
        new MappingJackson2HttpMessageConverter())
    .defaultResponseCharacterEncoding(UTF_8)
    .build();

long[] ids = {1, 1, 99};   // 1回目は承認、2回目は承認済、99 はない
for (long id : ids) {
    String url = "/api/requests/" + id + "/approve";
    var res = mvc.perform(post(url))
            .andReturn().getResponse();
    System.out.println("POST " + url + " → "
            + res.getStatus() + " " + res.getContentType());
    System.out.println("  " + res.getContentAsString());
}

